function saturateProcess(samples, opts){
  opts = opts || {};
  var drive = opts.drive != null ? opts.drive : 1.5;
  var mix = opts.mix != null ? opts.mix : 1;
  var bias = opts.bias != null ? opts.bias : 0;   // 偶次谐波偏置
  var out = new Array(samples.length);
  for(var i=0;i<samples.length;i++){
    var x = samples[i] + bias;
    var wet = Math.atan(x * drive) * (2/Math.PI);  // atan 软饱和，范围(-1,1)
    out[i] = x*(1-mix) + wet*mix;
  }
  return out;
}
function saturateAnalyze(samples, opts){
  var out = saturateProcess(samples, opts);
  var peak=0, sum=0;
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; }
  return { length: out.length, peak: peak, rms: Math.sqrt(sum/out.length) };
}

var EXPORTS={saturateAnalyze:saturateAnalyze,saturateProcess:saturateProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SaturationForgePure = EXPORTS; }
